use serde::{Deserialize,Serialize};
#[derive(Debug,Clone,Serialize,Deserialize)] pub struct Scenario{pub name:String,pub probability:f64,pub impact:f64}
#[derive(Debug,Clone,Serialize,Deserialize)] pub struct SimulationResult{pub iterations:u32,pub expected_impact:f64,pub worst_case_impact:f64,pub p95_impact:f64,pub budget_exhausted:bool,pub method:String}
pub fn simulate(scenarios:&[Scenario],requested:u32,budget:u32)->Result<SimulationResult,String>{if scenarios.is_empty(){return Err("at least one scenario required".into())}if scenarios.iter().any(|s|!s.probability.is_finite()||!s.impact.is_finite()||!(0.0..=1.0).contains(&s.probability)||s.impact<0.0){return Err("probabilities must be [0,1], impacts finite and non-negative".into())}let total:f64=scenarios.iter().map(|s|s.probability).sum();if total<=0.0||total>1.000001{return Err("probabilities must sum to (0,1]".into())}let n=requested.max(1).min(budget.max(1)).min(100_000);let mut samples=Vec::with_capacity(n as usize);let mut seed:u64=0x9E3779B97F4A7C15;for _ in 0..n{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);let draw=(seed>>11)as f64/((1u64<<53)as f64);let mut cumulative=0.0;let mut selected=&scenarios[scenarios.len()-1];for s in scenarios{cumulative+=s.probability/total;if draw<=cumulative{selected=s;break}}samples.push(selected.impact)}samples.sort_by(f64::total_cmp);let expected=scenarios.iter().map(|s|s.probability/total*s.impact).sum();let idx=(((samples.len()-1)as f64)*0.95).ceil()as usize;Ok(SimulationResult{iterations:n,expected_impact:expected,worst_case_impact:scenarios.iter().map(|s|s.impact).fold(0.0,f64::max),p95_impact:samples[idx],budget_exhausted:requested>n,method:"BOUNDED_DETERMINISTIC_WEIGHTED_SAMPLING_NOT_CAUSAL".into()})}
#[cfg(test)]mod tests{use super::*;#[test]fn budget_is_enforced(){let s=vec![Scenario{name:"base".into(),probability:1.0,impact:2.0}];let r=simulate(&s,500,20).unwrap();assert_eq!(r.iterations,20);assert!(r.budget_exhausted)}#[test]fn invalid_scenario_fails(){assert!(simulate(&[Scenario{name:"bad".into(),probability:1.2,impact:1.0}],5,5).is_err())}}
